        {
            Assert.Equal(DriveModel.C1540, profile.DefaultDriveModel);
            Assert.Equal(C1541ViceRomNames.Dos1540, profile.DefaultDriveDosRomName);
            Assert.NotEqual(DriveModel.C1541, profile.DefaultDriveModel);
        }
    }
}
