{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20MemoryMapTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Architectures.Vic20;
using ViceSharp.Core.Vic20;
using Xunit;

/// <summary>
/// FR-VIC20-002. Memory map and expansion regions.
/// </summary>
public sealed class Vic20MemoryMapTests
{
    [Theory]
    [InlineData(Vic20Expansion.Unexpanded, 0x0000, true)]
    [InlineData(Vic20Expansion.Unexpanded, 0x1000, true)]
    [InlineData(Vic20Expansion.Unexpanded, 0x0400, false)]
    [InlineData(Vic20Expansion.Unexpanded, 0x2000, false)]
    [InlineData(Vic20Expansion.Exp3K, 0x0400, true)]
    [InlineData(Vic20Expansion.Exp3K, 0x2000, false)]
    [InlineData(Vic20Expansion.Exp8K, 0x2000, true)]
    [InlineData(Vic20Expansion.Exp8K, 0x3FFF, true)]
    [InlineData(Vic20Expansion.Exp8K, 0x4000, false)]
    [InlineData(Vic20Expansion.Exp16K, 0x4000, true)]
    [InlineData(Vic20Expansion.Exp24K, 0x6000, true)]
    [InlineData(Vic20Expansion.Exp32K, 0xA000, true)]
    [InlineData(Vic20Expansion.Exp32K, 0x0400, true)]
    public void Expansion_InstallsExpectedRam(Vic20Expansion expansion, int address, bool installed)
    {
        Assert.Equal(installed, Vic20MemoryLayout.IsInstalledRam(expansion, (ushort)address));
    }

    [Fact]
    public void UnexpandedMachine_OpenBusExpansion_ReadsAsFf_AndBaseRamWritable()
    {
        var machine = MachineTestFactory.CreateVic20Machine();

        machine.Bus.Write(0x1000, 0xAB);
        Assert.Equal(0xAB, machine.Bus.Read(0x1000));

        // Unexpanded BLK1 is open; builder fills 0xFF and SimpleRam still accepts writes
        // for MVP (software that probes expansion sees 0xFF until expanded).
        Assert.Equal(0xFF, machine.Bus.Peek(0x2000));
    }

    [Fact]
    public void Exp8KMachine_Blk1IsWritable()
    {
        var descriptor = new Vic20Descriptor().WithExpansion(Vic20Expansion.Exp8K);
        var machine = MachineTestFactory.CreateVic20Machine(descriptor);

        machine.Bus.Write(0x2000, 0x5A);
        machine.Bus.Write(0x3FFF, 0xA5);
        Assert.Equal(0x5A, machine.Bus.Read(0x2000));
        Assert.Equal(0xA5, machine.Bus.Read(0x3FFF));
        // BLK2 still open
        Assert.Equal(0xFF, machine.Bus.Peek(0x4000));
    }

    [Fact]
    public void IoWindow_ViaAndVicStillMapped()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        // Write VIC register and read back
        machine.Bus.Write(0x900F, 0x1B);
        Assert.Equal(0x1B, machine.Bus.Read(0x900F));
        // VIA2 base responds (DDRB default 0)
        Assert.Equal(0x00, machine.Bus.Read(0x9122)); // DDRB
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20KeyboardTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Chips.IEC;
using ViceSharp.Core.Vic20;
using Xunit;

/// <summary>
/// FR-VIC20-003, FR-VIC20-004. Keyboard matrix and joystick via VIA ports.
/// </summary>
public sealed class Vic20KeyboardTests
{
    [Fact]
    public void Matrix_SetKey_AppearsInScanRowsForColumns()
    {
        var matrix = new Vic20KeyboardMatrix();
        // Press key at row 0, column 0 (digit '1' on VIC-20 matrix)
        matrix.SetKey(0, 0, true);

        // Column 0 driven low -> row 0 bit low
        var rows = matrix.ScanRowsForColumns(columnSelectActiveLow: 0xFE);
        Assert.Equal(0xFE, rows); // bit 0 cleared

        matrix.SetKey(0, 0, false);
        rows = matrix.ScanRowsForColumns(0xFE);
        Assert.Equal(0xFF, rows);
    }

    [Fact]
    public void Machine_KeyboardInject_VisibleOnVia2PortA()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var matrix = machine.Devices.GetAll<Vic20KeyboardMatrix>().Single();
        var via2 = machine.Devices.GetAll<Via6522>().Single(v => v.BaseAddress == 0x9120);

        // Select column 0: DDRB=$FF, ORB=$FE (drive bit0 low)
        machine.Bus.Write(0x9122, 0xFF); // DDRB
        machine.Bus.Write(0x9120, 0xFE); // ORB

        matrix.SetKey(1, 0, true); // row1 col0 = '3'

        var pra = machine.Bus.Read(0x9121); // ORA/IRA
        Assert.True((pra & 0x02) == 0, $"expected row1 low, PRA=${pra:X2}");
    }

    [Fact]
    public void Joystick_Right_ClearsVia2PortBBit7()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var matrix = machine.Devices.GetAll<Vic20KeyboardMatrix>().Single();

        matrix.JoystickMask = 0x08; // right
        // DDRB input (0) so PortBInput contributes
        machine.Bus.Write(0x9122, 0x00);
        var prb = machine.Bus.Read(0x9120);
        Assert.True((prb & 0x80) == 0, $"expected PB7 low for right, PRB=${prb:X2}");
    }

    [Fact]
    public void DualVia_Windows_RemainAt9110And9120()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var vias = machine.Devices.GetAll<Via6522>().OrderBy(v => v.BaseAddress).ToArray();
        Assert.Equal(2, vias.Length);
        Assert.Equal(0x9110, vias[0].BaseAddress);
        Assert.Equal(0x9120, vias[1].BaseAddress);
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20VideoTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Abstractions;
using ViceSharp.Chips.Vic;
using Xunit;

/// <summary>
/// FR-VIC20-001. VIC-I character-mode frames (not black-stub-only).
/// </summary>
public sealed class Vic20VideoTests
{
    [Fact]
    public void CharacterMode_RendersNonBlackPixels_ForKnownScreenPattern()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var vic = Assert.IsType<Mos6561>(machine.Devices.GetByRole(DeviceRole.VideoChip));

        // Plant 'A' (screen code 1) with white color at screen base $1E00
        const ushort screen = 0x1E00;
        machine.Bus.Write(screen, 0x01); // 'A'
        machine.Bus.Write(0x9400, 0x01); // white

        // Ensure VIC points at unexpanded screen / chargen ROM
        machine.Bus.Write(0x9002, 22);
        machine.Bus.Write(0x9005, 0xF0);

        vic.RenderNow();

        Assert.True(vic.FrameWidth >= 8);
        Assert.True(vic.FrameHeight >= 8);
        var fb = vic.FrameBuffer;
        var nonBlack = 0;
        for (var i = 0; i < fb.Length; i += 4)
        {
            if (fb[i] != 0 || fb[i + 1] != 0 || fb[i + 2] != 0)
                nonBlack++;
        }

        Assert.True(nonBlack > 0, "character-mode frame should contain non-black pixels for glyph 'A'");
    }

    [Fact]
    public void FrameCompleted_FiresAfterFullRaster()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var vic = Assert.IsType<Mos6561>(machine.Devices.GetByRole(DeviceRole.VideoChip));
        var frames = 0;
        vic.FrameCompleted += (_, _) => frames++;

        // One full PAL frame = 71 * 312 cycles
        var cycles = vic.CyclesPerLine * vic.TotalLines;
        for (var i = 0; i < cycles; i++)
            machine.Clock.Step();

        Assert.True(frames >= 1, $"expected FrameCompleted, got {frames}");
    }

    [Fact]
    public void PalAndNtsc_Profiles_ExposeDistinctTiming()
    {
        var pal = MachineTestFactory.CreateVic20Machine("vic20");
        var ntsc = MachineTestFactory.CreateVic20Machine("vic20ntsc");
        var palVic = Assert.IsType<Mos6561>(pal.Devices.GetByRole(DeviceRole.VideoChip));
        var ntscVic = Assert.IsType<Mos6561>(ntsc.Devices.GetByRole(DeviceRole.VideoChip));

        Assert.Equal(71, palVic.CyclesPerLine);
        Assert.Equal(312, palVic.TotalLines);
        Assert.Equal(65, ntscVic.CyclesPerLine);
        Assert.Equal(261, ntscVic.TotalLines);
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20BootProofTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using System.Text;
using ViceSharp.Abstractions;
using ViceSharp.Core.Vic20;
using Xunit;

/// <summary>
/// FR-PRF-005 / FR-VIC20-002. READY-like fingerprint after boot with real ROMs.
/// </summary>
public sealed class Vic20BootProofTests
{
    /// <summary>
    /// Use case: unexpanded VIC-20 with official ROMs boots through KERNAL/BASIC
    /// and paints READY. into screen RAM.
    /// Acceptance: within 400 frames, screen codes 18,5,1,4,25 appear in $1000-$1FFF.
    /// </summary>
    [Fact]
    public void Vic20_Boot_Reaches_Ready_Prompt()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        const int maxFrames = 400;

        for (var frame = 0; frame < maxFrames; frame++)
        {
            machine.RunFrame();
            if (TryFindReady(machine, out var addr))
            {
                Assert.InRange(addr, 0x1000, 0x1FFF);
                return;
            }
        }

        Assert.Fail(DumpBootFailure(machine, maxFrames));
    }

    [Fact]
    public void Vic20_AfterReset_RomsAndResetVector_FromProductionBuilder()
    {
        var machine = MachineTestFactory.CreateVic20Machine();
        var basic = MachineTestFactory.LoadVic20Rom("basic-901486-01.bin").Span;
        var kernal = MachineTestFactory.LoadVic20Rom("kernal.901486-07.bin").Span;

        Assert.Equal(basic[0], machine.Bus.Read(0xC000));
        Assert.Equal(kernal[0], machine.Bus.Read(0xE000));
        var lo = machine.Bus.Read(0xFFFC);
        var hi = machine.Bus.Read(0xFFFD);
        var vector = (ushort)(lo | (hi << 8));
        Assert.Equal(vector, machine.GetState().PC);
        Assert.NotEqual((ushort)0, vector);
    }

    [Fact]
    public void Vic20_CartPrg_MapsIntoBlkRegion()
    {
        // Minimal PRG: load at $A000, 4 payload bytes
        var prg = new byte[] { 0x00, 0xA0, 0x11, 0x22, 0x33, 0x44 };
        var cart = Vic20Cartridge.FromPrg(prg);
        var descriptor = new Architectures.Vic20.Vic20Descriptor().WithCartridge(cart);
        var machine = MachineTestFactory.CreateVic20Machine(descriptor);

        Assert.Equal(0x11, machine.Bus.Read(0xA000));
        Assert.Equal(0x44, machine.Bus.Read(0xA003));
    }

    private static bool TryFindReady(IMachine machine, out ushort addr)
    {
        for (var a = 0x1000; a < 0x2000 - 5; a++)
        {
            if (machine.Bus.Peek((ushort)a) == 18
                && machine.Bus.Peek((ushort)(a + 1)) == 5
                && machine.Bus.Peek((ushort)(a + 2)) == 1
                && machine.Bus.Peek((ushort)(a + 3)) == 4
                && machine.Bus.Peek((ushort)(a + 4)) == 25)
            {
                addr = (ushort)a;
                return true;
            }
        }

        addr = 0;
        return false;
    }

    private static string DumpBootFailure(IMachine machine, int maxFrames)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"READY not found after {maxFrames} frames. PC=${machine.GetState().PC:X4}");
        for (var i = 0; i < 88; i++)
        {
            var c = machine.Bus.Peek((ushort)(0x1E00 + i));
            sb.Append(c is >= 1 and <= 26 ? (char)('A' + c - 1) : c == 0x20 ? ' ' : '?');
        }
        return sb.ToString();
    }
}
"}

{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20DriveDefaultTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Abstractions;
using ViceSharp.Architectures.C1541;
using ViceSharp.Architectures.C64;
using ViceSharp.Architectures.Vic20;
using ViceSharp.Launcher;
using Xunit;

/// <summary>
/// FR-VIC20-006. Vic20 unit 8 defaults to 1540; C64 remains 1541.
/// </summary>
public sealed class Vic20DriveDefaultTests
{
    [Fact]
    public void Vic20Profile_DefaultDrive_IsC1540_FromProductionProfile()
    {
        var profile = Vic20MachineProfiles.Default;
        Assert.Equal(DriveModel.C1540, profile.DefaultDriveModel);
        Assert.Equal(C1541ViceRomNames.Dos1540, profile.DefaultDriveDosRomName);
        // Production constant must match the catalog name used by the drive builder.
        Assert.Equal("dos1540-325302+3-01.bin", profile.DefaultDriveDosRomName);
    }

    [Fact]
    public void C64Profile_DefaultDrivePath_Remains1541()
    {
        // C64 does not store DefaultDriveModel on profile; production drive default
        // for true-drive / topology is C1541 DOS name.
        Assert.Equal("dos1541-325302-01+901229-05.bin", C1541ViceRomNames.Dos1541);
        Assert.NotEqual(C1541ViceRomNames.Dos1540, C1541ViceRomNames.Dos1541);

        // Topology for x64sc drive attach does not inject dos1540.
        var args = ViceArgsParser.Parse("x64sc", new[] { "-8", "disk.d64" });
        var yaml = ViceTopologyBuilder.BuildYaml(args);
        Assert.Contains("kind: C64", yaml);
        Assert.DoesNotContain("dos1540", yaml);
        Assert.Contains("kind: C1541", yaml);
    }

    [Fact]
    public void XvicTopology_Drive8_InjectsDos1540()
    {
        var args = ViceArgsParser.Parse("xvic", new[] { "-8", "disk.d64" });
        var yaml = ViceTopologyBuilder.BuildYaml(args);
        Assert.Contains("kind: Vic20", yaml);
        Assert.Contains(C1541ViceRomNames.Dos1540, yaml);
    }

    [Fact]
    public void Vic20SystemCoreTraits_AdvertiseDefaultDrive()
    {
        var core = Vic20MachineProfiles.Default.SystemCore;
        Assert.True(core.Traits.TryGetValue("defaultDrive", out var drive));
        Assert.Equal(nameof(DriveModel.C1540), drive);
        Assert.True(core.Traits.TryGetValue("defaultDriveDos", out var dos));
        Assert.Equal(C1541ViceRomNames.Dos1540, dos);
    }
}
"}

