            root = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "native", "vice", "vice", "data"));
            if (!Directory.Exists(root))
                return; // skip only if no ROM root (should not happen in this repo)
