        try
        {
            var factory = new DefaultEmulatorRuntimeFactory();
            var registry = new EmulatorRuntimeRegistry();
            var emulatorHost = new EmulatorHostService(registry, factory);
            var settings = new SettingsServiceHost(registry, factory);

