                new UpdateSettingsRequest(
                    created.SessionId,
                    Limiter: null,
                    Display: null,
                    Input: null,
                    ProfileId: "vic20",
                    RestartSession: true),
                TestContext.Current.CancellationToken);

            Assert.True(updated.Status.IsSuccess, updated.Status.Message);
            Assert.Equal("vic20", updated.Settings!.ProfileId);

            Assert.True(registry.TryGet(created.SessionId, out var session));
            Assert.Contains("VIC-20", session!.Architecture.MachineName, StringComparison.OrdinalIgnoreCase);
            Assert.Equal("xvic", (session.Architecture as Abstractions.IProfiledArchitectureDescriptor)!.MachineProfile.Family);
            // Vic20 dual VIA present
            Assert.Equal(2, session.Machine.Devices.GetAll<Chips.IEC.Via6522>().Count());
        }
        finally
        {
            Environment.SetEnvironmentVariable("VICESHARP_ROM_PATH", null);
        }
    }
}"}

